alter table public.cineo_viewers add column genres text[] not null default '{}'; alter table public.cineo_parental add column failures integer not null default 0; alter table public.cineo_parental add column locked_until timestamptz; create table public.cineo_viewer_tokens(token_hash text primary key,viewer_id uuid not null references public.cineo_viewers(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,session_id uuid not null,expires_at timestamptz not null); create index cineo_viewer_tokens_owner on public.cineo_viewer_tokens(user_id); create index cineo_viewer_tokens_viewer on public.cineo_viewer_tokens(viewer_id); alter table public.cineo_viewer_tokens enable row level security; revoke all on public.cineo_viewer_tokens from anon,authenticated; grant all on public.cineo_viewer_tokens to service_role;
